def lingnan_followup(inputs,prior):
    packet=inputs.get('lingnan_exit_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('Lingnan packet changed')
    if prior is None or digest(prior)!=PRIOR_DIGEST or packet['prior_digest']!=PRIOR_DIGEST:raise ValueError('Lingnan prior changed')
    company=next(c for c in inputs['fixed_quote_audit']['original_prices']['companies']if c['symbol']=='002717')
    raw=next(s for s in inputs['fixed_quote_audit']['sources']if s['symbol']=='002717'and s['key']=='tencent_raw')
    scope={'company':company,'raw_source':raw,'catalog':inputs['endpoint_reasons']['catalog']}
    if digest(scope)!=SCOPE_DIGEST or packet['scope_digest']!=SCOPE_DIGEST:raise ValueError('Lingnan price/catalog scope changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=len(packet['sources'])or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('Lingnan sources changed')
    for aid,s in sources.items():
        if {k:v for k,v in s.items()if k!='texts'}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('Lingnan source identity changed')
        if len(s['texts'])!=s['pages']or [sha256(t.encode()).hexdigest()for t in s['texts']]!=PAGE_HASHES[aid]:raise ValueError('Lingnan pages changed')
        if s['announcement_date']>'2026-11-19':raise ValueError('Lingnan future source')
    if packet['visual_read']!=VISUAL:raise ValueError('Lingnan visual scope changed')
    for r in VISUAL:
        if r['source_sha256']!=sources[r['announcement_id']]['sha256']or r['page_text_sha256']!=PAGE_HASHES[r['announcement_id']][r['page']-1]or not r['verified']:raise ValueError('Lingnan visual binding changed')
    for r in RESULT['corrections']:
        if D(r['before'])+D(r['delta'])!=D(r['after']):raise ValueError('Lingnan correction arithmetic changed')
        text=re.sub(r'\s+','',sources[r['source']]['texts'][r['page']-1]).replace(',','')
        if any(r[k]not in text for k in ['before','delta','after']):raise ValueError('Lingnan correction source changed')
    for k in ['before','after']:
        if D(RESULT['corrections'][0][k])-D(RESULT['corrections'][1][k])!=D(RESULT['corrections'][2][k]):raise ValueError('Lingnan balance identity changed')
    q=RESULT['quarter'];text=re.sub(r'\s+','',sources[q['source']]['texts'][q['page']-1]).replace(',','')
    vals=[q['parent_equity'],q['prior_year_parent_equity_restated']]+[v for k in ['revenue','parent_profit','recurring_profit','operating_cash']for v in q[k].values()if v is not None]
    if any(x not in text for x in vals):raise ValueError('Lingnan quarter source changed')
    if sha256(raw['raw_text'].encode()).hexdigest()!=raw['sha256']:raise ValueError('Lingnan raw response changed')
    quotes=quotes_from_source(raw);rows=[r for r in company['rows']if '2026-09-07'<=r['date']<='2026-10-12'and r['has_trade']]
    if len(rows)!=20 or [r['date']for r in rows]!=RESULT['trigger']['dates']or any(D(str(r['raw_close']))>=1 or quotes[r['date']]!=D(str(r['raw_close']))for r in rows):raise ValueError('Lingnan trigger series changed')
    if packet['result']!=RESULT:raise ValueError('Lingnan interpretation changed')
    return deepcopy(RESULT)
